  /** define load %s %s */
  function p_load(t: T, a_stage: Value, a_fx: Value): void {
    if (listContains(G.l.Num_D_Stage1Props, ("stage" + String(a_stage)))) {
      t.v.scanfx = indexOf(G.l.Num_D_Stage2FX, ("stage" + String(a_stage)));
      if (eq(a_fx, 1)) {
        if (!gt(G.v.FlashFinal, 0)) {
          while (!eq(item(G.l.Num_D_Stage2FX, t.v.scanfx), "")) {
            t.v.scanfx = num(t.v.scanfx) + 1;
            p_List_Input_Key(t, item(G.l.Num_D_Stage2FX, t.v.scanfx), ":");
            p_place_prop(t, "1");
          }
        }
      } else {
        t.v.scanfx = indexOf(G.l.Num_D_Stage1Props, ("stage" + String(a_stage)));
        while (!eq(item(G.l.Num_D_Stage1Props, t.v.scanfx), "")) {
          t.v.scanfx = num(t.v.scanfx) + 1;
          p_List_Input_Key(t, item(G.l.Num_D_Stage1Props, t.v.scanfx), ":");
          p_place_prop(t, "");
        }
        if (gt(G.v.FlashFinal, 0)) {
          if (gt(G.v.FlashFinal, 300)) {
            t.setEffect("brightness", (num(G.v.FlashFinal) - 300));
          }
          t.setDirection(90);
          t.setEffect("ghost", (100 - num(G.v.FlashFinal)));
          t.setEffect("color", (num(item(G.l.ram, (54 + num((3 - num(G.v.bigfreeze)))))) + num((num(sin(num((num(G.v.FlashFinal) * 6)))) * 10))));
          t.setXY(0, 0);
          t.setSize(100);
          t.switchCostume("fx_flashyhit");
          t.stamp();
        }
      }
      t.switchCostume("nul");
      t.setSize(100);
    }
  }

