  /** define place prop %s */
  function p_place_prop(t: T, a_fx: Value): void {
    t.setRotationStyle("left-right");
    t.setDirection(90);
    if ((listContains(t.l.Local_Return2, "Month") && !eq(rt.current("MONTH"), item(t.l.Local_Return2, (1 + indexOf(t.l.Local_Return2, "Month")))))) {
      return;
    }
    if ((listContains(t.l.Local_Return2, "Day") && !eq(rt.current("DATE"), item(t.l.Local_Return2, (1 + indexOf(t.l.Local_Return2, "Day")))))) {
      return;
    }
    t.setXY(0, 0);
    t.switchCostume("nul2");
    t.setSize(num((num(item(t.l.Local_Return2, 4)) * num(G.v.camera))));
    t.switchCostume(item(t.l.Local_Return2, 1));
    p_allign_c_s(t, (num((num(item(t.l.Local_Return2, 2)) + num((num(G.v.scrollX_display) * num(item(t.l.Local_Return2, 5)))))) * num(G.v.camera)), (num((num(item(t.l.Local_Return2, 3)) + num((num(G.v.Scroll_Y_display) * num(item(t.l.Local_Return2, 5)))))) * num(G.v.camera)), "");
    t.setEffect("color", 0);
    t.setEffect("brightness", 0);
    t.setEffect("ghost", 0);
    t.v.sway = "0";
    t.v.misc5 = "0";
    p_specialFX(t, item(t.l.Local_Return2, 1));
    if (listContains(t.l.Local_Return2, "Dir")) {
      t.setRotationStyle("left-right");
      t.setDirection(num(item(t.l.Local_Return2, (1 + indexOf(t.l.Local_Return2, "Dir")))));
    }
    if (listContains(t.l.Local_Return2, "Tile")) {
      for (let i18 = Math.round(num(item(t.l.Local_Return2, (1 + indexOf(t.l.Local_Return2, "Tile"))))); i18-- > 0; ) {
        t.v.misc5 = num(t.v.misc5) + 1;
        p_sway(t);
        p_stamp(t, G.v.rain);
        if (contains(item(t.l.Local_Return2, 1), "fx_blade")) {
          p_allign_c_s(t, (num((num(item(G.l.Num_L_GrassRandom, t.v.misc5)) + num(G.v.scrollX_display))) * num(G.v.camera)), "", "x");
        } else {
          p_allign_c_s(t, (num((num((num(item(t.l.Local_Return2, 2)) + num((num(G.v.scrollX_display) * num(item(t.l.Local_Return2, 5)))))) * num(G.v.camera))) + num((num((num(item(t.l.Local_Return2, (2 + indexOf(t.l.Local_Return2, "Tile")))) * num(t.v.misc5))) * num(G.v.camera)))), "", "x");
        }
      }
    }
    p_sway(t);
    p_stamp(t, G.v.rain);
    t.setDirection(90);
    t.switchCostume("nul");
    t.hide();
  }

  /** define re */
  function p_re(t: T): void {
    t.stamp();
    if (eq(G.v.selectedLAYER, t.v.art_Num)) {
      t.setEffect("brightness", 0);
      t.setEffect("color", 0);
      t.setRotationStyle("don't rotate");
      t.switchCostume(("art" + String(G.v.artmode)));
      t.stamp();
    }
  }

  /** define allign %s %s c/s %s */
  function p_allign_c_s(t: T, a_x: Value, a_y: Value, a_cs: Value): void {
    t.v.storedcost = t.costumeName();
    t.switchCostume("big_image");
    if (eq(a_cs, "y")) {
      t.setXY(t.x, num(a_y));
    } else {
      if (eq(a_cs, "x")) {
        t.setXY(num(a_x), t.y);
      } else {
        if (eq(a_cs, "c")) {
          t.setXY(t.x + num(a_x), t.y);
          t.setXY(t.x, t.y + num(a_y));
        } else {
          t.setXY(num(a_x), num(a_y));
        }
      }
    }
    t.switchCostume(t.v.storedcost);
  }

  /** define specialFX %s */
  function p_specialFX(t: T, a_id: Value): void {
    if (listContains(G.l.Num_G_ModifierAll, 27)) {
      t.setEffect("brightness", 100);
    }
    if (listContains(G.l.Num_G_ModifierAll, 33)) {
      t.setEffect("color", -Infinity);
    }
    if (contains(a_id, "fx_glare")) {
      t.setEffect("ghost", (num(rt.pickRandom(0, 5)) + 40));
      t.setSize(num(rt.pickRandom(99, 100)));
      if (((gt(rt.current("HOUR"), 17) || lt(rt.current("HOUR"), 7)) && !listContains(t.l.Local_Return2, "Global"))) {
        t.setEffect("ghost", 100);
      }
      t.setXY(num(item(t.l.Local_Return2, 2)), num(item(t.l.Local_Return2, 3)));
    }
    if (eq(a_id, "Crowdhi")) {
      t.switchCostume(("Crowd" + String(item(G.l.Num_G_CDuplicates, item(t.l.Local_Return2, (1 + indexOf(t.l.Local_Return2, "ID")))))));
    }
    if (eq(a_id, "spec_citybg")) {
      p_ads(t, "BParallax4");
    }
    if (eq(a_id, "spec_cityfront")) {
      p_ads(t, "Parallax4");
    }
    if (eq(a_id, "spec_subway")) {
      t.v.adtimer = num(t.v.adtimer) + 1;
      if (eq(t.v.adtimer, 240)) {
        rt.startSound(t, "train2");
      }
      if (gt(t.v.adtimer, 280)) {
        t.switchCostume(("Parallax6Train" + String(Math.abs(num((num(mod(num(t.v.adtimer), 2)) + 1))))));
      }
      if (eq(t.v.adtimer, 350)) {
        t.v.adtimer = "0";
      }
    }
    if (eq(a_id, "prop_stage")) {
      t.setEffect("color", 0);
      t.switchCostume("prop_stage#1");
      if ((gt(rt.current("HOUR"), 17) || lt(rt.current("HOUR"), 7))) {
        t.switchCostume("prop_stage#2");
        t.setEffect("color", (num((num(G.v.fauxtimer) * 10)) + num((num(t.v.clapFX) * 5))));
        t.setEffect("brightness", (num(t.v.clapFX) * 2));
      }
    }
    if (eq(a_id, "fx_flare")) {
      if ((gt(rt.current("HOUR"), 17) || lt(rt.current("HOUR"), 7))) {
        t.setEffect("color", (num((num(G.v.fauxtimer) * 10)) + num((num(t.v.clapFX) * 5))));
        t.setEffect("brightness", (num(t.v.clapFX) * 2));
      } else {
        t.setEffect("ghost", 100);
      }
    }
    if ((eq(a_id, "prop_hamboffice") || eq(a_id, "prop_officefloor"))) {
      t.setEffect("color", item(G.l.Num_G_SRandom, 1));
      t.setEffect("brightness", item(G.l.Num_G_SRandom, 2));
    }
  }

